/* Actionable banking workspace. Snapshot, period results and daily work stay distinct. */
let executiveQueue='overdue';
function executiveCall(name,...args){return E(name+'('+args.map(x=>JSON.stringify(x)).join(',')+')')}
function executiveModel(){
 const m=dashboardModel(),today=demoToday(),daily=m.tasks.filter(t=>taskScheduledDay(t)===today),dailyDone=daily.filter(t=>t.status==='Selesai'),dailyCancelled=daily.filter(t=>t.status==='Dibatalkan'),dailyOpen=daily.filter(isOpen),leadLate=m.leads.filter(l=>typeof leadSla==='function'&&leadSla(l).late),closed=m.opps.filter(o=>['Won','Lost','Cancelled'].includes(o.outcome)&&dashboardInPeriod(o.closed));
 const won=closed.filter(o=>o.outcome==='Won'),lost=closed.filter(o=>o.outcome==='Lost'),cancelled=closed.filter(o=>o.outcome==='Cancelled');
 return {...m,closed,won,lost,cancelled,winRate:won.length+lost.length?Math.round(won.length/(won.length+lost.length)*100):null,today,daily,dailyDone,dailyCancelled,dailyOpen,leadLate,completion:daily.length-dailyCancelled.length?Math.round(dailyDone.length/(daily.length-dailyCancelled.length)*100):null};
}
const executiveRecordsBefore=dashboardRecords;
dashboardRecords=function(kind,arg){const m=executiveModel();const extra={managedLeads:['Leads dalam pengelolaan',m.leads.filter(l=>!['Dikonversi ke Customer','Dikonversi ke Opportunity','Tidak Qualified','Ditutup'].includes(leadLifecycle(l))),'lead'],source:['Lead baru · '+arg,m.newLeads.filter(l=>(l.source||'Belum diisi')===arg),'lead'],today:['Task terjadwal hari ini',m.daily,'task'],leadSla:['Lead melewati SLA',m.leadLate,'lead'],won:['Berhasil pada periode',m.won,'opp'],lost:['Lost pada periode',m.lost,'opp'],cancelled:['Cancelled pada periode',m.cancelled,'opp']};return extra[kind]||executiveRecordsBefore(kind,arg)};
function executiveFocus(key){if(!['overdue','leadSla','sla','noNext','approvals'].includes(key))return;executiveQueue=key;renderContent()}
function executivePeriod(value){dashboardRange=value;renderContent()}
function executiveIcon(name){const paths={pipeline:'<rect x="3" y="4" width="5" height="16" rx="1"/><rect x="10" y="4" width="5" height="11" rx="1"/><rect x="17" y="4" width="4" height="6" rx="1"/>',lead:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m3-14v6m-3-3h6"/>',customer:'<path d="m3 8 9-5 9 5M4 9h16M5 20h14M7 10v7m5-7v7m5-7v7"/>',task:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="m8 12 3 3 5-6M9 3h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};return '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.task)+'</svg>'}
function executiveMetric(label,value,note,kind,icon){return '<button class="ex-metric" onclick="'+executiveCall('dashboardOpen',kind)+'"><span class="ex-metric-top"><span>'+label+'</span>'+executiveIcon(icon)+'</span><strong>'+E(value)+'</strong><small>'+E(note)+'</small></button>'}
function executiveRow(record,kind){const task=kind==='task',lead=kind==='lead',route=task?'Aktivitas detail':lead?'Lead detail':'Opportunity detail',name=task?record.purpose:lead?pname(record.profile):record.name;const meta=task?(record.type+' · '+pname(record.profile)):lead?(record.product||record.need||'Lead'):(record.product+' · '+dashboardCompactMoney(record.value));return '<button class="ex-record" onclick="'+executiveCall('dashboardNavigate',route,record.id)+'"><span class="ex-record-main"><strong>'+E(name)+'</strong><small>'+E(meta)+'</small></span><span class="ex-record-side"><b>'+E(record.owner||'Belum ada AO')+'</b><small>'+E(task?fmt(record.scheduled):lead?leadLifecycle(record):record.stage)+'</small></span></button>'}
function executivePerformancePanel(){
 const entry=pocPerformanceCache.get(pocKey('performance')),data=entry?.data;
 return '<section class="ex-panel ex-targets"><div class="ex-panel-head"><div><span class="ex-eyebrow">KINERJA BISNIS</span><h2>Target & realisasi</h2><p>'+E(pocEffectiveScope()==='all'?'Semua cabang dalam akses Anda':activeBranch)+' · periode bulanan tersendiri</p></div><button onclick="go(\'Target & Kinerja\')">Lihat rincian</button></div><div class="ex-target-controls"><label>Bulan<input type="month" aria-label="Bulan target dashboard" value="'+E(pocPeriod)+'" onchange="pocUpdate(\'period\',this.value)"></label>'+(pocCentral()?'<label>Cakupan<select aria-label="Cakupan target dashboard" onchange="pocUpdate(\'scope\',this.value)"><option value="branch" '+(pocScope==='branch'?'selected':'')+'>Cabang aktif</option><option value="all" '+(pocScope==='all'?'selected':'')+'>Semua cabang</option></select></label>':'')+'<span>Realisasi terkonfirmasi · bukan nominal pipeline</span></div>'+(data?'<div class="ex-target-grid">'+[['Kredit','credit'],['Dana','funding'],['Layanan','service']].map(([label,key])=>{const actual=data.branchRows.reduce((n,r)=>n+Number(r[key]||0),0),target=data.branchRows.reduce((n,r)=>n+Number(r.target?.[key]||0),0),pct=target>0?Math.round(actual/target*100):null;return '<button class="ex-target" onclick="go(\'Target & Kinerja\')"><span>'+label+'<b>'+E(pct===null?'Tanpa target':pct+'%')+'</b></span><strong>'+E(dashboardCompactMoney(actual))+'</strong><small>Target '+E(target>0?dashboardCompactMoney(target):'belum ditetapkan')+'</small><span class="ex-progress"><i style="width:'+Math.max(0,Math.min(100,pct||0))+'%"></i></span></button>'}).join('')+'</div>'+(data.unconfirmedWon?.length?'<p class="ex-target-note">'+data.unconfirmedWon.length+' Won belum memiliki bukti realisasi lengkap dan belum dihitung dalam pencapaian.</p>':''):'<p class="ex-loading" role="status">'+E(entry?.error||'Memuat target dan realisasi…')+'</p>')+'</section>';
}
const executivePerformanceBefore=pocPerformancePanel;
pocPerformancePanel=function(full=false){return !full&&view==='Monitoring'?executivePerformancePanel():executivePerformanceBefore(full)};
comprehensiveDashboard=function(){
 const m=executiveModel(),period=dashboardRange==='all'?'Seluruh periode':dashboardStart()+' – '+demoToday(),account=currentAccount(),owners=[...new Set([...m.opps,...m.tasks,...m.leads].map(x=>x.owner).filter(Boolean))].sort(),available=[...new Set([...db.opps,...db.tasks,...db.leads].filter(mine).map(x=>x.owner).filter(Boolean))].sort();
 const groups=stageDefs().filter(s=>s.type==='process'&&(s.active||m.active.some(o=>o.stageId===s.id||o.stage===s.name))).map(s=>({...s,rows:m.active.filter(o=>o.stageId===s.id||o.stage===s.name)})),maxValue=Math.max(1,...groups.map(s=>s.rows.reduce((n,o)=>n+(Number(o.value)||0),0)));
 const queues={overdue:['Task overdue',m.over,'task'],leadSla:['SLA Leads',m.leadLate,'lead'],sla:['SLA Opportunity',m.sla,'opp'],noNext:['Tanpa Task berikutnya',m.noNext,'opp'],approvals:['Persetujuan',m.approvals,'task']},chosen=queues[executiveQueue]||queues.overdue,rows=chosen[1].slice().sort((a,b)=>chosen[2]==='task'?sortPriority(a,b):String(a.id).localeCompare(String(b.id)));
 const daily=m.daily.slice().sort((a,b)=>Number(isOpen(b))-Number(isOpen(a))||String(a.scheduled).localeCompare(String(b.scheduled))),todayLabel=new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Makassar',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());
 return '<div class="executive-dashboard"><header class="ex-heading"><div><span class="ex-eyebrow">BPD BALI / RELATIONSHIP MANAGEMENT</span><h1>Setiap relasi. Peluang berikutnya.</h1><p>Halo, '+E(account.name.split(' ')[0])+'. Ini posisi bisnis dan pekerjaan yang perlu perhatian Anda.</p></div><div class="ex-heading-actions">'+(pocReadOnly()?'':btn('Buat Task','newTask()',true))+btn('Buka pipeline',"go('Peluang');chooseCRMView('Pipeline')")+'</div></header><div class="ex-context"><span class="ex-branch">'+E(activeBranch||userBranchLabel())+'</span><span>'+E(authUser?.role||'Simulasi')+'</span><span>'+E(todayLabel)+' · WITA</span><span class="ex-data-label">Data dummy POC</span></div><div class="ex-toolbar"><div><strong>Ringkasan bisnis</strong><small>Posisi aktif saat ini · sesuai akses Anda</small></div><label>AO<select aria-label="Penanggung jawab dashboard" onchange="dashboardFilter(\'owner\',this.value)"><option value="">Semua AO dalam akses</option>'+available.map(o=>'<option value="'+E(o)+'" '+(dashboardOwner===o?'selected':'')+'>'+E(o)+'</option>').join('')+'</select></label></div><div class="ex-metrics">'+executiveMetric('Pipeline aktif',dashboardCompactMoney(m.value),m.active.length+' opportunity · nilai indikatif','value','pipeline')+executiveMetric('Leads dalam pengelolaan',m.leads.filter(l=>!['Dikonversi ke Customer','Dikonversi ke Opportunity','Tidak Qualified','Ditutup'].includes(leadLifecycle(l))).length,m.leadLate.length+' melewati SLA','managedLeads','lead')+executiveMetric('Customer aktif',m.customers.filter(p=>(p.customerStatus||'Aktif')==='Aktif').length,'Profil dan relasi Customer 360','customers','customer')+executiveMetric('Task hari ini',m.daily.length,m.dailyDone.length+' selesai · '+m.dailyOpen.length+' masih terbuka','today','task')+'</div><div class="ex-main-grid"><section class="ex-panel ex-pipeline"><div class="ex-panel-head"><div><span class="ex-eyebrow">PELUANG BISNIS</span><h2>Kesehatan pipeline</h2><p>Posisi aktif per tahap · klik untuk melihat detail</p></div><span class="ex-count">'+m.active.length+' aktif</span></div><div class="ex-stage-chart">'+(groups.map(s=>{const total=s.rows.reduce((n,o)=>n+(Number(o.value)||0),0);return '<button class="ex-stage" onclick="'+executiveCall('dashboardOpen','stage',s.id)+'"><span class="ex-stage-heading"><b>'+E(s.name)+'</b><strong>'+E(dashboardCompactMoney(total))+'</strong></span><span class="ex-stage-track"><i style="width:'+Math.max(0,Math.min(100,total/maxValue*100))+'%"></i></span><small>'+s.rows.length+' opportunity</small></button>'}).join('')||'<p>Belum ada tahap aktif yang dikonfigurasi.</p>')+'</div><footer class="ex-panel-footer"><span>Distribusi nominal saat ini, bukan funnel konversi.</span><button onclick="go(\'Peluang\');chooseCRMView(\'Pipeline\')">Lihat pipeline</button></footer></section><section class="ex-panel ex-daily"><div class="ex-panel-head"><div><span class="ex-eyebrow">AGENDA KERJA</span><h2>Fokus hari ini</h2><p>Task terjadwal hari ini · tidak mengikuti filter periode hasil</p></div>'+executiveIcon('clock')+'</div><div class="ex-daily-summary"><strong>'+m.dailyDone.length+'<small> / '+(m.daily.length-m.dailyCancelled.length)+'</small></strong><span>Task selesai<small>'+m.dailyCancelled.length+' dibatalkan, di luar persentase</small></span><b>'+E(m.completion===null?'—':m.completion+'%')+'</b></div><div class="ex-progress"><i style="width:'+(m.completion||0)+'%"></i></div><div class="ex-daily-list">'+(daily.slice(0,4).map(t=>'<button class="ex-daily-row" onclick="'+executiveCall('dashboardNavigate','Aktivitas detail',t.id)+'"><span class="ex-time">'+E(new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Makassar',hour:'2-digit',minute:'2-digit'}).format(parseCRMDate(t.scheduled)))+'</span><span><strong>'+E(t.purpose)+'</strong><small>'+E(pname(t.profile))+' · '+E(t.owner)+'</small></span><em class="'+(t.status==='Selesai'?'complete':overdue(t)?'late':'')+'">'+E(overdue(t)?'Overdue':t.status)+'</em></button>').join('')||'<div class="ex-empty">Belum ada Task terjadwal hari ini.<small>Jadwalkan follow-up dari Leads, Customer 360, atau Opportunity.</small></div>')+'</div><button class="ex-text-button" onclick="dashboardOpen(\'today\')">Lihat '+m.daily.length+' Task hari ini</button></section></div><section class="ex-panel ex-attention"><div class="ex-panel-head"><div><span class="ex-eyebrow">PERLU DITINDAKLANJUTI</span><h2>Prioritas yang tidak boleh terlewat</h2><p>Aturan SLA dan jadwal CRM, sesuai AO dan cabang aktif.</p></div><button onclick="go(\'Notifikasi\')">Buka notifikasi</button></div><div class="ex-queue-tabs" role="group" aria-label="Prioritas dashboard">'+Object.entries(queues).map(([key,[name,items]])=>'<button class="'+(executiveQueue===key?'active':'')+'" aria-pressed="'+(executiveQueue===key)+'" onclick="'+executiveCall('executiveFocus',key)+'">'+name+'<b>'+items.length+'</b></button>').join('')+'</div><div class="ex-priority-list">'+(rows.slice(0,4).map(x=>executiveRow(x,chosen[2])).join('')||'<div class="ex-empty">Tidak ada '+E(chosen[0].toLowerCase())+' pada cakupan ini.<small>Pilih kategori lain untuk meninjau tindak lanjut.</small></div>')+'</div><button class="ex-text-button" onclick="'+executiveCall('dashboardOpen',executiveQueue)+'">Lihat seluruh '+E(chosen[0].toLowerCase())+'</button></section><div class="ex-results-heading"><div><span class="ex-eyebrow">HASIL & AKUISISI</span><h2>Hasil pada periode</h2><p>'+E(period)+' · WITA</p></div><label>Periode<select aria-label="Periode hasil dashboard" onchange="executivePeriod(this.value)">'+[['7','7 hari terakhir'],['30','30 hari terakhir'],['month','Bulan ini'],['all','Seluruh periode']].map(([v,label])=>'<option value="'+v+'" '+(dashboardRange===v?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div><div class="ex-results"><section class="ex-panel ex-closing"><div class="ex-closing-heading"><h3>Hasil penutupan Opportunity</h3><span>Win rate <b>'+E(m.winRate===null?'—':m.winRate+'%')+'</b></span></div><div class="ex-outcomes">'+[['Berhasil (Won)','won',m.won],['Lost','lost',m.lost],['Cancelled','cancelled',m.cancelled]].map(([label,key,items])=>'<button class="'+key+'" onclick="'+executiveCall('dashboardOpen',key)+'"><span>'+label+'</span><strong>'+items.length+'</strong><small>'+E(dashboardCompactMoney(items.reduce((n,o)=>n+(Number(o.value)||0),0)))+'</small></button>').join('')+'</div><p class="ex-note">Menurut tanggal penutupan. Win rate = Won ÷ (Won + Lost); Cancelled tidak dihitung. Nominal opportunity bukan realisasi.</p></section><section class="ex-panel ex-acquisition"><h3>Leads baru</h3><button class="ex-acquisition-total" onclick="dashboardOpen(\'leads\')"><strong>'+m.newLeads.length+'</strong><span>leads dibuat pada periode ini</span></button>'+[...new Set(m.newLeads.map(l=>l.source||'Belum diisi'))].sort().map(source=>'<button class="ex-source" onclick="'+executiveCall('dashboardOpen','source',source)+'"><span>'+E(source)+'</span><b>'+m.newLeads.filter(l=>(l.source||'Belum diisi')===source).length+'</b></button>').join('')+(!m.newLeads.length?'<p class="ex-note">Belum ada Lead baru pada periode terpilih.</p>':'')+'</section></div><div id="executive-performance-slot"></div><section class="ex-panel"><div class="ex-panel-head"><div><span class="ex-eyebrow">KAPASITAS TIM</span><h2>Portofolio & beban kerja AO</h2><p>Snapshot saat ini · klik AO untuk melihat opportunity aktifnya</p></div></div><div class="ex-team">'+(owners.map(owner=>{const os=m.active.filter(o=>o.owner===owner),ts=m.tasks.filter(t=>t.owner===owner&&isOpen(t)),late=ts.filter(overdue).length;return '<button class="ex-team-row" onclick="'+executiveCall('dashboardOpen','owner',owner)+'"><span class="ex-avatar">'+E(owner.split(' ').slice(0,2).map(x=>x[0]).join(''))+'</span><span class="ex-team-name"><strong>'+E(owner)+'</strong><small>'+os.length+' opportunity aktif</small></span><span><strong>'+E(dashboardCompactMoney(os.reduce((n,o)=>n+(Number(o.value)||0),0)))+'</strong><small>nominal pipeline</small></span><span><strong>'+ts.length+'</strong><small>Task terbuka</small></span><span class="'+(late?'ex-warning':'')+'"><strong>'+late+'</strong><small>overdue</small></span></button>'}).join('')||'<p class="ex-note">Belum ada data AO dalam cakupan ini.</p>')+'</div></section><footer class="ex-page-footer"><span>Data dummy POC · tanpa integrasi Core Banking · sesuai hak akses akun</span><span>Snapshot CRM '+E(fmt(now()))+' WITA</span></footer></div>';
};
const executiveRenderBefore=renderContent;
renderContent=function(){executiveRenderBefore();if(view!=='Monitoring')return;const app=document.querySelector('#app'),panel=app?.querySelector('.ex-targets'),slot=app?.querySelector('#executive-performance-slot');if(panel&&slot)slot.append(panel)};
if(typeof authUser!=='undefined'&&authUser&&!choosingBranch)render();
